head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getSortableStatus]<br/>sortable=true 일때 GridView 에 실행된 정렬 상태 정보를 1차원 배열로 반환합니다.",
    "validation" : [
        "Header 와 Body 가 MultiLine 인 경우 정렬은 동일 Column 단위로 실행되지만 정렬 상태 정보는 정렬이 적용된 Body Column 정보가 반환됩니다.",
        "다중 정렬이 실행된 경우 정렬이 실행된 순번에 맞게 배열이 생성됩니다.",
        "실행된 정렬이 없는 경우 빈 배열을 반환합니다.",
        "result.colID 는 정렬이 실행된 Header Column 과 매칭되는 Body Column 의 ID 값을 갖습니다.",
        "result.sortOrder 는 1(오름차순), -1(내림차순) 값을 갖습니다.",
        "result.dataType 는 매칭 Body Column 의 dataType 속성값을 갖습니다.",
        "Header Column 의 개별 sortable 설정 시 GridView 의 sortable 이 무시되고, 미설정 시 GridView 의 sortable 이 적용됩니다.",
        "onsort 이벤트 핸들러 내에서 getSortableStatus() 를 실행하면 방금 실행된 정렬의 최신 상태를 조회할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  - GridView sortable="true" : 개별 미설정 Header(col3, col4)의 기본 정렬 가능 (@spec1)
    //  - MultiLine 병합헤더(2 Row) : 상단 [그룹A(col1,col2)][col3][col4] / 하단 [col1][col2]
    //  - 개별 sortable : col1=true(GridView 무시X) / col2=false(GridView 무시) / col3,col4=미설정(GridView 적용)
    $c.gcm.createLabel('label="sortable 컬럼(col1 개별true, col3·col4 GridView)의 헤더를 클릭하면 정렬되고 onsort 에서 상태가 출력됩니다. Ctrl 키를 누른 채 다른 컬럼 헤더를 클릭하면 다중 정렬됩니다(순번대로 배열). 단일 클릭은 해당 컬럼만 정렬(기존 정렬 해제). col2(개별false)는 정렬되지 않습니다. 정렬 전엔 [getSortableStatus 확인]이 빈 배열을 반환합니다."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성 (col1=text, col2=number, col3=text, col4=number)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="number"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 정렬 시 순서가 바뀌도록 값을 섞어서 구성
    let jsonData = [
        { "col1": "C", "col2": 200, "col3": "Cc", "col4": 30 },
        { "col1": "A", "col2": 400, "col3": "Aa", "col4": 10 },
        { "col1": "D", "col2": 100, "col3": "Dd", "col4": 40 },
        { "col1": "B", "col2": 300, "col3": "Bb", "col4": 20 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정 (createCList 공통 함수)
    //  - sortable="true"        : 개별 미설정 Header(col3, col4)의 기본 정렬 가능 (@spec1)
    //  - rowNumVisible="true"   : RowNum Column 표시
    //  - rowStatusVisible="true": RowStatus Column 표시
    //  - groupbyZone 미설정      : 헤더 클릭이 정렬로 동작하도록 함 (groupbyZone=true 면 정렬 미동작)
    let properties = {
        dataList: "data:dlt_bind",
        sortable: "true",
        rowNumVisible: "true",
        rowStatusVisible: "true",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';

    // target 생성 (Body 4컬럼, MultiLine 병합 헤더 2 Row)
    //  헤더 상단 Row : [그룹A colspan=2 rowspan=1 width=120][col3 rowspan=2][col4 rowspan=2]
    //  헤더 하단 Row : [col1][col2]
    //  개별 sortable : hcol1=true / hcol2=false / hcol3·hcol4=미설정(GridView true 적용)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' sortEvent="onclick" id="" style="width:700px;height:240px;" ev:onsort="scwin.target1_onsort">';
    strTarget += '<w2:caption style="" id="caption1" value="getSortableStatus 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    // 단일 Row 헤더 (병합 그룹 제거 - 병합 시 헤더->Body 컬럼 인덱스가 어긋나 클릭 정렬이 잘못된 Column 에 적용됨, MCP 실측)
    strTarget += '<w2:row style="" id="hrow1">';
    // col1 : 개별 sortable=true
    strTarget += '<w2:column width="120" style="" inputType="text" sortable="true" id="hcol1" value="col1(개별true)"></w2:column>';
    // col2 : 개별 sortable=false (GridView true 무시 -> 정렬 불가)
    strTarget += '<w2:column width="120" style="" inputType="text" sortable="false" id="hcol2" value="col2(개별false)"></w2:column>';
    // col3 : 개별 미설정 (GridView true 적용)
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol3" value="col3(GridView)"></w2:column>';
    // col4 : 개별 미설정 (GridView true 적용)
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol4" value="col4(GridView)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // col1 (text) - 개별 sortable=true
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    // col2 (number) - 개별 sortable=false
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="number" id="col2" dataList="col2"></w2:column>';
    // col3 (text) - 개별 미설정(GridView sortable=true 적용)
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    // col4 (number) - 개별 미설정(GridView sortable=true 적용)
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="number" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// onsort 이벤트 핸들러 (@spec2 핵심)
//  - 사용자가 sortable 헤더를 클릭해 정렬하면 발생
//  - 핸들러 내에서 getSortableStatus() 실행 시 방금 실행된 정렬의 최신 상태 조회 (@spec2)
//  - 반환 객체 배열 : colID(매칭 Body Column ID) / sortOrder(1,-1) / dataType(매칭 Body Column dataType)
//  - 다중 정렬 시 정렬이 실행된 순번대로 배열 생성
scwin.target1_onsort = function (info) {
    let status = target1.getSortableStatus();
    wf_body_bottom.getObj("scwin").setReturnValue("[onsort] 정렬 후 getSortableStatus() : " + JSON.stringify(status));
};



// getSortableStatus 확인 : 현재 실행된 정렬 상태 정보를 1차원 배열로 반환
//  - 정렬 전이면 빈 배열 (실행된 정렬이 없는 경우 @return)
scwin.btn_getSortableStatus_onclick = function () {
    let status = target1.getSortableStatus();
    wf_body_bottom.getObj("scwin").setReturnValue(JSON.stringify(status));
}
